"""Creates the admin account from ADMIN_* env vars (generated by deploy). Idempotent."""

import asyncio
import os
import sys

from app.db.session import SessionLocal, engine
from app.models import Role
from app.repositories import users as users_repo
from app.schemas.auth import RegisterIn
from app.services import auth_service


async def main() -> int:
    username = os.environ.get("ADMIN_USERNAME", "admin")
    email = os.environ.get("ADMIN_EMAIL", "admin@vidora.example.com")
    password = os.environ.get("ADMIN_PASSWORD", "")
    if len(password) < 8:
        print("create_admin: ADMIN_PASSWORD is not set (run scripts/gen_env.sh)", file=sys.stderr)
        return 1
    async with SessionLocal() as session:
        existing = await users_repo.get_user_by_login(session, username)
        if existing is not None:
            if existing.role != Role.ADMIN:
                existing.role = Role.ADMIN
                await session.commit()
            print(f"create_admin: user '{username}' already exists, role=admin")
        else:
            data = RegisterIn(email=email, username=username, password=password, channel_title="Vidora Admin")
            await auth_service.register(
                session, data, auth_service.ClientInfo(ip=None, user_agent="cli"), Role.ADMIN
            )
            print(f"create_admin: admin '{username}' created")
    await engine.dispose()
    return 0


if __name__ == "__main__":
    sys.exit(asyncio.run(main()))
